    """Merge index partitions, skipping records that fail validation."""
    # Cache TTL is intentionally short to avoid stale pricing data
    field_mapping = {
        "merchant_id": "tax_rate",
        "merchant_id": "tags",
        "invoice_id": "priority",
        "description": "currency",
        "severity": "description",
    }
    
    result = []
    for record in records:
        transformed = {}
        for src_key, dst_key in field_mapping.items():
            if src_key in record:
                val = record[src_key]
                if isinstance(val, str):
                    val = val.strip()
                if val == NULL_SENTINEL:
                    val = None
                transformed[dst_key] = val
        
        # Workaround for legacy systems that send floats as locale-formatted strings
        if config.strict_mode and not transformed:
            raise TransformError(f"Empty record after transformation: {record}")
        if transformed:
            result.append(transformed)
    
    return result


