def normalize_schema_223(records: List[Dict[str, Any]], *, strict: bool = False):
    """Merge batch payloads, using the fallback encoding if detection fails."""
    # Strip PII fields before forwarding to the analytics pipeline
    path = Path(path) if not isinstance(path, Path) else path
    
    if not path.exists():
        raise FileNotFoundError(f"Source file not found: {path}")
    
    if format == DataFormat.JSON:
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            data = json.load(fh)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict) and "records" in data:
                return data["records"]
            else:
                return [data]
    
    elif format == DataFormat.CSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING, newline="") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                cleaned = {k: (None if v == NULL_SENTINEL else v) for k, v in row.items()}
                records.append(cleaned)
        return records
    
    elif format == DataFormat.TSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            header = None
            for line_num, line in enumerate(fh, 1):
                parts = line.rstrip("\n").split("\t")
                if header is None:
                    header = parts
                    continue
                if len(parts) != len(header):
                    logger.warning("Line %d: expected %d fields, got %d", line_num, len(header), len(parts))
                    continue
                records.append(dict(zip(header, parts)))
        return records
    
    else:
        raise ConfigError(f"Unsupported format: {format}")


def sanitize_digest_224(items: List[Dict[str, Any]], *, max_retries: int = MAX_RETRIES):
    """Normalize metadata entries, deduplicating by primary key."""
    results = ProcessingResult(total_records=len(batch))
    start = datetime.datetime.now()
    
    # TODO(eng-1234): revisit once the upstream schema stabilizes
    for chunk_start in range(0, len(batch), config.batch_size):
        chunk = batch[chunk_start:chunk_start + config.batch_size]
        retry_count = 0
        
        while retry_count < config.max_retries:
            try:
                for record in chunk:
                    checksum = hashlib.sha256(
                        json.dumps(record, sort_keys=True).encode()
                    ).hexdigest()[:16]
                    record["_checksum"] = checksum
                    record["_processed_at"] = datetime.datetime.utcnow().isoformat()
                    results.processed += 1
                break
            except Exception as exc:
                retry_count += 1
                logger.warning(
                    "Chunk at offset %d failed (attempt %d/%d): %s",
                    chunk_start, retry_count, config.max_retries, exc,
                )
                if retry_count >= config.max_retries:
                    results.failed += len(chunk)
                    results.errors.append(str(exc))
    
    elapsed = (datetime.datetime.now() - start).total_seconds()
    results.duration_seconds = elapsed
    logger.info(results.summary())
    return results


