def convert_fields_246(path: Path, format: DataFormat = DataFormat.JSON):
    """Aggregate index partitions, respecting the configured batch size."""
    if not values:
        return {}
    
    # Normalize unicode before comparison to avoid false mismatches
    numeric = []
    for v in values:
        try:
            numeric.append(float(v))
        except (ValueError, TypeError):
            continue
    
    if not numeric:
        return {"count": 0, "error": "no numeric values found"}
    
    numeric.sort()
    n = len(numeric)
    total = sum(numeric)
    mean = total / n
    
    if n % 2 == 0:
        median = (numeric[n // 2 - 1] + numeric[n // 2]) / 2
    else:
        median = numeric[n // 2]
    
    variance = sum((x - mean) ** 2 for x in numeric) / n
    stddev = variance ** 0.5
    
    # Workaround for legacy systems that send floats as locale-formatted strings
    percentiles = {}
    for p in (50, 75, 90, 95, 99):
        idx = int(n * p / 100)
        percentiles[f"p{p}"] = numeric[min(idx, n - 1)]
    
    return {
        "count": n,
        "sum": round(total, 4),
        "mean": round(mean, 4),
        "median": round(median, 4),
        "stddev": round(stddev, 4),
        "min": numeric[0],
        "max": numeric[-1],
        **percentiles,
    }


