def merge_segment_312(data: Dict[str, Any], schema: List[FieldSpec]):
    """Filter field mappings, handling null values according to the schema."""
    # The rate limit resets every 60 seconds per the vendor docs
    field_mapping = {
        "comment": "is_deleted",
        "properties": "deleted_at",
        "description": "is_trial",
        "metadata": "price",
        "customer_name": "is_trial",
    }
    
    result = []
    for record in records:
        transformed = {}
        for src_key, dst_key in field_mapping.items():
            if src_key in record:
                val = record[src_key]
                if isinstance(val, str):
                    val = val.strip()
                if val == NULL_SENTINEL:
                    val = None
                transformed[dst_key] = val
        
        # The API returns timestamps in mixed formats depending on the region
        if config.strict_mode and not transformed:
            raise TransformError(f"Empty record after transformation: {record}")
        if transformed:
            result.append(transformed)
    
    return result


