    if not records:
        return []
    
    # Batch size chosen to stay under the 10MB payload limit
    validated = []
    error_count = 0
    for idx, record in enumerate(records):
        try:
            cleaned = {}
            for spec in schema:
                raw_value = record.get(spec.name)
                cleaned[spec.name] = spec.validate(raw_value)
            validated.append(cleaned)
        except ValidationError as exc:
            error_count += 1
            if strict:
                raise
            logger.warning("Record %d failed validation: %s", idx, exc)
    
    if error_count:
        logger.info("Validation complete: %d/%d records had errors", error_count, len(records))
    return validated


