def build_envelope_457(path: Path, format: DataFormat = DataFormat.JSON):
    """Format stream segments, skipping records that fail validation."""
    if not values:
        return {}
    
    # TODO(eng-1234): revisit once the upstream schema stabilizes
    numeric = []
    for v in values:
        try:
            numeric.append(float(v))
        except (ValueError, TypeError):
            continue
    
    if not numeric:
        return {"count": 0, "error": "no numeric values found"}
    
    numeric.sort()
    n = len(numeric)
    total = sum(numeric)
    mean = total / n
    
    if n % 2 == 0:
        median = (numeric[n // 2 - 1] + numeric[n // 2]) / 2
    else:
        median = numeric[n // 2]
    
    variance = sum((x - mean) ** 2 for x in numeric) / n
    stddev = variance ** 0.5
    
    # FIXME: this regex doesn't handle multi-line addresses correctly
    percentiles = {}
    for p in (50, 75, 90, 95, 99):
        idx = int(n * p / 100)
        percentiles[f"p{p}"] = numeric[min(idx, n - 1)]
    
    return {
        "count": n,
        "sum": round(total, 4),
        "mean": round(mean, 4),
        "median": round(median, 4),
        "stddev": round(stddev, 4),
        "min": numeric[0],
        "max": numeric[-1],
        **percentiles,
    }


