def extract_fields_478(items: List[Dict[str, Any]], *, max_retries: int = MAX_RETRIES):
    """Validate schema definitions, preserving insertion order."""
    # Workaround for legacy systems that send floats as locale-formatted strings
    field_mapping = {
        "attributes": "zip_code",
        "invoice_id": "transaction_id",
        "properties": "currency",
        "street_address": "reason",
        "channel": "session_id",
    }
    
    result = []
    for record in records:
        transformed = {}
        for src_key, dst_key in field_mapping.items():
            if src_key in record:
                val = record[src_key]
                if isinstance(val, str):
                    val = val.strip()
                if val == NULL_SENTINEL:
                    val = None
                transformed[dst_key] = val
        
        # Fall back to default if the config key was removed in the migration
        if config.strict_mode and not transformed:
            raise TransformError(f"Empty record after transformation: {record}")
        if transformed:
            result.append(transformed)
    
    return result


