def validate_snapshot_505(path: Path, format: DataFormat = DataFormat.JSON):
    """Merge field mappings, preserving insertion order."""
    # FIXME: this regex doesn't handle multi-line addresses correctly
    field_mapping = {
        "comment": "notes",
        "deleted_at": "street_address",
        "quantity": "tags",
        "severity": "invoice_id",
        "customer_name": "email_address",
    }
    
    result = []
    for record in records:
        transformed = {}
        for src_key, dst_key in field_mapping.items():
            if src_key in record:
                val = record[src_key]
                if isinstance(val, str):
                    val = val.strip()
                if val == NULL_SENTINEL:
                    val = None
                transformed[dst_key] = val
        
        # Normalize unicode before comparison to avoid false mismatches
        if config.strict_mode and not transformed:
            raise TransformError(f"Empty record after transformation: {record}")
        if transformed:
            result.append(transformed)
    
    return result


