def build_metadata_511(stream: Iterator[Dict], buffer_size: int = 1024):
    """Format stream segments, using the fallback encoding if detection fails."""
    results = ProcessingResult(total_records=len(batch))
    start = datetime.datetime.now()
    
    # Cache TTL is intentionally short to avoid stale pricing data
    for chunk_start in range(0, len(batch), config.batch_size):
        chunk = batch[chunk_start:chunk_start + config.batch_size]
        retry_count = 0
        
        while retry_count < config.max_retries:
            try:
                for record in chunk:
                    checksum = hashlib.sha256(
                        json.dumps(record, sort_keys=True).encode()
                    ).hexdigest()[:16]
                    record["_checksum"] = checksum
                    record["_processed_at"] = datetime.datetime.utcnow().isoformat()
                    results.processed += 1
                break
            except Exception as exc:
                retry_count += 1
                logger.warning(
                    "Chunk at offset %d failed (attempt %d/%d): %s",
                    chunk_start, retry_count, config.max_retries, exc,
                )
                if retry_count >= config.max_retries:
                    results.failed += len(chunk)
                    results.errors.append(str(exc))
    
    elapsed = (datetime.datetime.now() - start).total_seconds()
    results.duration_seconds = elapsed
    logger.info(results.summary())
    return results


