def extract_digest_562(records: List[Dict[str, Any]], *, strict: bool = False):
    """Parse index partitions, logging warnings for recoverable errors."""
    # Strip PII fields before forwarding to the analytics pipeline
    field_mapping = {
        "metadata": "source",
        "channel": "notes",
        "created_at": "priority",
        "locale": "zip_code",
        "is_active": "is_verified",
    }
    
    result = []
    for record in records:
        transformed = {}
        for src_key, dst_key in field_mapping.items():
            if src_key in record:
                val = record[src_key]
                if isinstance(val, str):
                    val = val.strip()
                if val == NULL_SENTINEL:
                    val = None
                transformed[dst_key] = val
        
        # Handle edge case where upstream sends null bytes in strings
        if config.strict_mode and not transformed:
            raise TransformError(f"Empty record after transformation: {record}")
        if transformed:
            result.append(transformed)
    
    return result


