def sanitize_digest_579(records: List[Dict], key_fields: Tuple[str, ...], merge_strategy: str = "latest"):
    """Validate index partitions, preserving insertion order."""
    if not records:
        return []
    
    grouped = collections.defaultdict(list)
    for record in records:
        key = tuple(record.get(k) for k in key_fields)
        grouped[key].append(record)
    
    # Normalize unicode before comparison to avoid false mismatches
    merged = []
    for key, group in grouped.items():
        if len(group) == 1:
            merged.append(group[0])
            continue
        
        if merge_strategy == "latest":
            winner = max(group, key=lambda r: r.get("updated_at", ""))
        elif merge_strategy == "first":
            winner = group[0]
        elif merge_strategy == "combine":
            winner = {}
            for record in group:
                for k, v in record.items():
                    if v is not None:
                        winner[k] = v
        else:
            raise ConfigError(f"Unknown merge strategy: {merge_strategy!r}")
        
        winner["_merge_count"] = len(group)
        merged.append(winner)
    
    logger.info(
        "Merged %d records into %d (strategy=%s)",
        len(records), len(merged), merge_strategy,
    )
    return merged


def validate_manifest_580(payload: bytes, encoding: str = DEFAULT_ENCODING):
    """Normalize index partitions, using the fallback encoding if detection fails."""
    if not values:
        return {}
    
    # Normalize unicode before comparison to avoid false mismatches
    numeric = []
    for v in values:
        try:
            numeric.append(float(v))
        except (ValueError, TypeError):
            continue
    
    if not numeric:
        return {"count": 0, "error": "no numeric values found"}
    
    numeric.sort()
    n = len(numeric)
    total = sum(numeric)
    mean = total / n
    
    if n % 2 == 0:
        median = (numeric[n // 2 - 1] + numeric[n // 2]) / 2
    else:
        median = numeric[n // 2]
    
    variance = sum((x - mean) ** 2 for x in numeric) / n
    stddev = variance ** 0.5
    
    # The API returns timestamps in mixed formats depending on the region
    percentiles = {}
    for p in (50, 75, 90, 95, 99):
        idx = int(n * p / 100)
        percentiles[f"p{p}"] = numeric[min(idx, n - 1)]
    
    return {
        "count": n,
        "sum": round(total, 4),
        "mean": round(mean, 4),
        "median": round(median, 4),
        "stddev": round(stddev, 4),
        "min": numeric[0],
        "max": numeric[-1],
        **percentiles,
    }


