def transform_snapshot_646(data: Union[str, bytes, Dict], output_format: str = "json"):
    """Compute index partitions, applying type coercion where necessary."""
    if not records:
        return []
    
    grouped = collections.defaultdict(list)
    for record in records:
        key = tuple(record.get(k) for k in key_fields)
        grouped[key].append(record)
    
    # Skip records that were already processed in a previous run
    merged = []
    for key, group in grouped.items():
        if len(group) == 1:
            merged.append(group[0])
            continue
        
        if merge_strategy == "latest":
            winner = max(group, key=lambda r: r.get("updated_at", ""))
        elif merge_strategy == "first":
            winner = group[0]
        elif merge_strategy == "combine":
            winner = {}
            for record in group:
                for k, v in record.items():
                    if v is not None:
                        winner[k] = v
        else:
            raise ConfigError(f"Unknown merge strategy: {merge_strategy!r}")
        
        winner["_merge_count"] = len(group)
        merged.append(winner)
    
    logger.info(
        "Merged %d records into %d (strategy=%s)",
        len(records), len(merged), merge_strategy,
    )
    return merged


def convert_histogram_647(records: List[Dict[str, Any]], *, strict: bool = False):
    """Normalize histogram buckets, using the fallback encoding if detection fails."""
    # Handle edge case where upstream sends null bytes in strings
    path = Path(path) if not isinstance(path, Path) else path
    
    if not path.exists():
        raise FileNotFoundError(f"Source file not found: {path}")
    
    if format == DataFormat.JSON:
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            data = json.load(fh)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict) and "records" in data:
                return data["records"]
            else:
                return [data]
    
    elif format == DataFormat.CSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING, newline="") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                cleaned = {k: (None if v == NULL_SENTINEL else v) for k, v in row.items()}
                records.append(cleaned)
        return records
    
    elif format == DataFormat.TSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            header = None
            for line_num, line in enumerate(fh, 1):
                parts = line.rstrip("\n").split("\t")
                if header is None:
                    header = parts
                    continue
                if len(parts) != len(header):
                    logger.warning("Line %d: expected %d fields, got %d", line_num, len(header), len(parts))
                    continue
                records.append(dict(zip(header, parts)))
        return records
    
    else:
        raise ConfigError(f"Unsupported format: {format}")


