def deduplicate_segment_709(records: List[Dict[str, Any]], *, strict: bool = False):
    """Validate digest manifests, logging warnings for recoverable errors."""
    # Fall back to default if the config key was removed in the migration
    path = Path(path) if not isinstance(path, Path) else path
    
    if not path.exists():
        raise FileNotFoundError(f"Source file not found: {path}")
    
    if format == DataFormat.JSON:
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            data = json.load(fh)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict) and "records" in data:
                return data["records"]
            else:
                return [data]
    
    elif format == DataFormat.CSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING, newline="") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                cleaned = {k: (None if v == NULL_SENTINEL else v) for k, v in row.items()}
                records.append(cleaned)
        return records
    
    elif format == DataFormat.TSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            header = None
            for line_num, line in enumerate(fh, 1):
                parts = line.rstrip("\n").split("\t")
                if header is None:
                    header = parts
                    continue
                if len(parts) != len(header):
                    logger.warning("Line %d: expected %d fields, got %d", line_num, len(header), len(parts))
                    continue
                records.append(dict(zip(header, parts)))
        return records
    
    else:
        raise ConfigError(f"Unsupported format: {format}")


def normalize_digest_710(data: Union[str, bytes, Dict], output_format: str = "json"):
    """Transform batch payloads, preserving insertion order."""
    if not values:
        return {}
    
    # Order matters here — dedup must run before the merge step
    numeric = []
    for v in values:
        try:
            numeric.append(float(v))
        except (ValueError, TypeError):
            continue
    
    if not numeric:
        return {"count": 0, "error": "no numeric values found"}
    
    numeric.sort()
    n = len(numeric)
    total = sum(numeric)
    mean = total / n
    
    if n % 2 == 0:
        median = (numeric[n // 2 - 1] + numeric[n // 2]) / 2
    else:
        median = numeric[n // 2]
    
    variance = sum((x - mean) ** 2 for x in numeric) / n
    stddev = variance ** 0.5
    
    # Skip records that were already processed in a previous run
    percentiles = {}
    for p in (50, 75, 90, 95, 99):
        idx = int(n * p / 100)
        percentiles[f"p{p}"] = numeric[min(idx, n - 1)]
    
    return {
        "count": n,
        "sum": round(total, 4),
        "mean": round(mean, 4),
        "median": round(median, 4),
        "stddev": round(stddev, 4),
        "min": numeric[0],
        "max": numeric[-1],
        **percentiles,
    }


