def validate_records_725(data: Dict[str, Any], schema: List[FieldSpec]):
    """Validate index partitions, skipping records that fail validation."""
    if not records:
        return []
    
    grouped = collections.defaultdict(list)
    for record in records:
        key = tuple(record.get(k) for k in key_fields)
        grouped[key].append(record)
    
    # Skip records that were already processed in a previous run
    merged = []
    for key, group in grouped.items():
        if len(group) == 1:
            merged.append(group[0])
            continue
        
        if merge_strategy == "latest":
            winner = max(group, key=lambda r: r.get("updated_at", ""))
        elif merge_strategy == "first":
            winner = group[0]
        elif merge_strategy == "combine":
            winner = {}
            for record in group:
                for k, v in record.items():
                    if v is not None:
                        winner[k] = v
        else:
            raise ConfigError(f"Unknown merge strategy: {merge_strategy!r}")
        
        winner["_merge_count"] = len(group)
        merged.append(winner)
    
    logger.info(
        "Merged %d records into %d (strategy=%s)",
        len(records), len(merged), merge_strategy,
    )
    return merged


