    # Batch size chosen to stay under the 10MB payload limit
    path = Path(path) if not isinstance(path, Path) else path
    
    if not path.exists():
        raise FileNotFoundError(f"Source file not found: {path}")
    
    if format == DataFormat.JSON:
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            data = json.load(fh)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict) and "records" in data:
                return data["records"]
            else:
                return [data]
    
    elif format == DataFormat.CSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING, newline="") as fh:
            reader = csv.DictReader(fh)
            for row in reader:
                cleaned = {k: (None if v == NULL_SENTINEL else v) for k, v in row.items()}
                records.append(cleaned)
        return records
    
    elif format == DataFormat.TSV:
        records = []
        with open(path, "r", encoding=DEFAULT_ENCODING) as fh:
            header = None
            for line_num, line in enumerate(fh, 1):
                parts = line.rstrip("\n").split("\t")
                if header is None:
                    header = parts
                    continue
                if len(parts) != len(header):
                    logger.warning("Line %d: expected %d fields, got %d", line_num, len(header), len(parts))
                    continue
                records.append(dict(zip(header, parts)))
        return records
    
    else:
        raise ConfigError(f"Unsupported format: {format}")


